changeSet.sql:
-- Le pas de 5 min n'existe plus comme pas d'affichage de la grille UPDATE salon_talk_planning SET configuration = jsonb_set(configuration, '{intervalMinutes}', '15'::jsonb, true) WHERE configuration IS NOT NULL AND (configuration ->> 'intervalMinutes')::int = 5;
-- Pas de placement (heures de début possibles) UPDATE salon_talk_planning SET configuration = jsonb_set(configuration, '{placementIntervalMinutes}', '15'::jsonb, true) WHERE configuration IS NOT NULL AND NOT jsonb_exists(configuration, 'placementIntervalMinutes');
-- Durées et battements par type : reproduisent les durées précédentes (60 et 75 min) UPDATE salon_talk_planning SET configuration = jsonb_set(configuration, '{talkTypes}', '{"CONFERENCE":{"durationTalkMinutes":45,"preparationMinutes":0,"cleanupMinutes":15}, "WORKSHOP":{"durationTalkMinutes":60,"preparationMinutes":0,"cleanupMinutes":15}}'::jsonb, true) WHERE configuration IS NOT NULL AND NOT jsonb_exists(configuration, 'talkTypes');
